Lấy dữ liệu và tự quản lý cache theo queryKey.

function DanhSach() {
  const { data, isPending, error } = useQuery({
    queryKey: ['san-pham', trang],
    queryFn: () => fetch(`/api/sp?trang=${trang}`).then((r) => r.json()),
    staleTime: 60_000,          // coi là còn mới trong 1 phút
  });
  if (isPending) return <p>Đang tải...</p>;
  if (error) return <p>Lỗi</p>;
  return data.map((sp) => <TheSanPham key={sp.id} sp={sp} />);
}

