Middleware là hàm (req, res, next) chạy TRƯỚC route: ghi log, kiểm tra đăng nhập, parse body... gọi next() để chuyển sang bước tiếp.

app.use((req, res, next) => {
  console.log(req.method, req.url);
  next();
});
function canDangNhap(req, res, next) {
  if (!req.headers.authorization) return res.status(401).json({ loi: 'Chưa đăng nhập' });
  next();
}
