- Trên bảng lớn, một số lệnh ALTER khóa cả bảng lâu; nên chạy qua migration ngoài giờ cao điểm

View là một câu SELECT được đặt tên, dùng như một bảng ảo; dữ liệu vẫn nằm ở bảng gốc.

CREATE VIEW doanh_thu_thang AS
SELECT date_trunc('month', ngay) AS thang, SUM(tong) AS doanh_thu
FROM don_hang
