Viết test bằng describe / test và kiểm tra kết quả bằng expect với các matcher.

import { describe, test, expect } from 'vitest';
import { tinhTong } from './gio-hang';

describe('tinhTong', () => {
  test('cộng giá x số lượng', () => {
    expect(tinhTong([{ gia: 100, sl: 2 }])).toBe(200);
