- Zig báo lỗi biến var không bao giờ bị sửa và biến không dùng tới; đó là lỗi biên dịch, không phải cảnh báo

Hàm có thể lỗi trả về kiểu !T (error union); try chuyển lỗi lên hàm gọi, catch xử lý tại chỗ.

const LoiDoc = error{ KhongThay, SaiDinhDang };

fn docTuoi(s: []const u8) !u8 {
    return std.fmt.parseInt(u8, s, 10) catch return LoiDoc.SaiDinhDang;
}
pub fn main() !void {
    const t = try docTuoi("20");
    const u = docTuoi("abc") catch 0;     // lỗi thì dùng 0
    _ = .{ t, u };
}

Mọi cấp phát bộ nhớ đi qua một allocator truyền tường minh; defer giải phóng khi rời khối.

var gpa = std.heap.GeneralPurposeAllocator(.{}){};
defer _ = gpa.deinit();              // báo rò rỉ bộ nhớ khi thoát
const alloc = gpa.allocator();

const buf = try alloc.alloc(u8, 100);
defer alloc.free(buf);

var ds = std.ArrayList(i32).init(alloc);
defer ds.deinit();
try ds.append(42);

Chạy code lúc biên dịch; generic của Zig chỉ là hàm nhận kiểu làm tham số comptime.

fn lonNhat(comptime T: type, a: T, b: T) T {
    return if (a > b) a else b;
}
const x = lonNhat(i32, 3, 7);

fn Hop(comptime T: type) type {
