Bọc một đối tượng / hàm để thêm hành vi (ghi log, cache, kiểm tra quyền) mà không sửa code gốc và giữ nguyên cách gọi.

function coCache(fn) {
  const cache = new Map();
  return async (id) => {
    if (!cache.has(id)) cache.set(id, await fn(id));
    return cache.get(id);
  };
}
function coLog(fn) {
  return async (...args) => { console.time(fn.name); try { return await fn(...args); } finally { console.timeEnd(fn.name); } };
}
const layUser = coLog(coCache(layUserTuDb));

