Kiểu test chuẩn của Go: một bảng các trường hợp, chạy từng cái bằng t.Run.

func TestChia(t *testing.T) {
    ds := []struct {
        ten      string
        a, b     int
        muon     int
        coLoi    bool
    }{
        {"bình thường", 7, 2, 3, false},
        {"chia 0", 1, 0, 0, true},
    }
    for _, tc := range ds {
        t.Run(tc.ten, func(t *testing.T) {
            got, err := Chia(tc.a, tc.b)
            if (err != nil) != tc.coLoi || got != tc.muon {
                t.Fatalf("Chia(%d,%d) = %d, %v", tc.a, tc.b, got, err)
            }
        })
    }
}

