export function useChuot() {
  const x = ref(0), y = ref(0);
  const cap = (e) => { x.value = e.pageX; y.value = e.pageY; };
  onMounted(() => window.addEventListener('mousemove', cap));
  onUnmounted(() => window.removeEventListener('mousemove', cap));
  return { x, y };
}

