class SpSpider(scrapy.Spider):
    name = "sp"
    start_urls = ["https://vidu.vn/sp"]
    def parse(self, resp):
        for sp in resp.css(".sp"):
            yield {"ten": sp.css("h3::text").get(), "gia": sp.css(".gia::text").get()}
        yield from resp.follow_all(css="a.trang-sau", callback=self.parse)

